// EVERY PHASE D MIGRATION CARRIES A ROLLBACK CLASSIFICATION, AND THE ONES THAT NEED A DOWN SCRIPT
// HAVE ONE.
//
// docs/phase-d/PHASE_D_ROLLBACK_CLASSIFICATION_D9.md classifies by hand and has gone short three
// times: it covered 66 files, then 73, then 87, each count true when written. On 23 Aug 2026 the
// corpus was 197. A hand-written table of a growing corpus is exactly the failure this check exists
// to make impossible — nothing compares a prose document against the files it claims to cover, so
// it goes short in silence.
//
// The classification is generated by scripts/phase_d/build_migration_rollback_classification.mjs.
// This check regenerates it and asserts three things about the result:
//   1. every scripts/sql/phase_d_*.sql file is classified, and none is UNCLASSIFIED;
//   2. every file whose class requires an explicit down script has one on disk;
//   3. the committed CSV is what regenerating produces — so a new migration reddens CI until the
//      deliverable is rebuilt, rather than the deliverable quietly describing an older corpus.
//
// It reads files only. No database credential, so it runs in the ordinary checks job.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, existsSync } from 'node:fs';
import { FILES, classify, introducedBy } from '../phase_d/build_migration_rollback_classification.mjs';

const CSV = 'docs/phase-d/PHASE_D_MIGRATION_ROLLBACK_CLASSIFICATION.csv';
const rows = FILES.map(classify);

test('every Phase D migration is classified', () => {
  assert.ok(FILES.length > 0, 'no scripts/sql/phase_d_*.sql files found — the population cannot be empty');
  const unclassified = rows.filter(r => r.class === 'UNCLASSIFIED');
  assert.deepEqual(unclassified.map(r => r.file), [],
    'a Phase D migration this program cannot classify is a rollback plan nobody has made');
});

test('every migration that needs an explicit down script has one', () => {
  const missing = rows.filter(r => r.down_script === 'MISSING');
  assert.deepEqual(missing.map(r => `${r.file} (${r.additive_ddl})`), [],
    'additive DDL with no down script: a previous function body is not a rollback for a table, '
    + 'column, constraint, trigger or index');
});

test('a down script drops the routines its migration introduced', () => {
  // `create or replace function` reads the same whether it is the first definition or the ninth,
  // and the two need opposite rollbacks. A routine no other file under scripts/sql/ defines was
  // INTRODUCED, and re-applying a predecessor cannot restore what had none. Measured 23 Aug 2026:
  // 28 down scripts reversed their file's tables, columns and triggers and left the routine behind.
  const bad = [];
  for (const f of FILES) {
    const intro = introducedBy(f);
    if (!intro.length) continue;
    const d = `scripts/sql/down/${f.replace(/\.sql$/, '')}_down.sql`;
    if (!existsSync(d)) { bad.push(`${f}: no down script, and it introduces ${intro.map(r => r.name).join(', ')}`); continue; }
    const t = readFileSync(d, 'utf8');
    for (const r of intro) if (!t.includes(r.name)) bad.push(`${d} does not drop ${r.name}`);
  }
  assert.deepEqual(bad, []);
});

test('the committed classification CSV covers the corpus that exists now', () => {
  assert.ok(existsSync(CSV), `${CSV} is not committed; run the builder`);
  const text = readFileSync(CSV, 'utf8');
  // The header states the population it was built over. A CSV listing fewer files than the tree
  // holds is the prose document's defect with a different extension.
  const listed = text.split('\n').filter(l => l.startsWith('"phase_d_')).length;
  assert.equal(listed, FILES.length,
    `the committed classification lists ${listed} migrations and scripts/sql holds ${FILES.length}; `
    + 'rebuild it with node scripts/phase_d/build_migration_rollback_classification.mjs');
  for (const r of rows) {
    assert.ok(text.includes(`"${r.file}","${r.class}"`),
      `${r.file} is classified ${r.class} now and the committed CSV does not say so`);
  }
});
